        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "El espectáculo de lo bello, en cualquier forma que se presente, levanta la mente a nobles aspiraciones.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "El recuerdo que deja un libro, es más importante que el libro mismo.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "La soledad es muy hermosa... cuando se tiene junto a alguien a quien decírselo.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Mi existencia, reducida al momento presente, flota en el océano de las cosas creadas como uno de esos átomos luminosos que nadan en el rayo del sol.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Podrá no haber poetas, pero siempre habrá poesía.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "¿Qué es poesía? Y tú me lo preguntas. Poesía... eres tú.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Por una mirada, un mundo; por una sonrisa, un cielo; por un beso... ¡Yo no sé qué te diera por un beso!", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "¡Lástima que el amor un diccionario no tenga donde hallar cuándo el orgullo es simplemente orgullo y cuándo es dignidad!", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Los suspiros son aire y van al aire. Las lágrimas son agua y van al mar. Dime mujer, cuando el amor se olvida, ¿Sabes tú adónde va?", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "¡Llora! No te avergüences de confesar que me has querido un poco. ¡Llora! Nadie nos mira. Ya ves; yo soy un hombre... y también lloro.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "La mujer hermosa, cuando pule el acero y contempla su imagen, se deleita en sí misma; pero al cabo busca otros ojos donde fijar los suyos, y si no los encuentra, se aburre.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "La imaginación de los muchachos es un corcel, y la curiosidad, la espuela que lo aguijonea y lo arrastra a través de los proyectos más imposibles.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Todo huye a fundirse en la cabeza de Siva, cuyo cerebro es el caos, cuyos ojos son la destrucción y cuya esencia es la nada.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "La soledad es el imperio de la conciencia.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "El amor es un rayo de luna.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "... Manrique amaba la soledad, y la amaba de tal modo, que algunas veces hubiera deseado no tener sombra, porque su sombra no le siguiese a todas partes.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Las aguas saltaron en chispas de luz y se cerraron sobre su cuerpo, y sus círculos de plata fueron ensanchándose, ensanchándose, hasta expirar en las orillas.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "La sonrisa de Daniel había llegado a hacerse proverbial en todo Toledo, y su mansedumbre, a prueba de las jugarretas más pesadas y las burlas y rechiflas de sus vecinos, no conocía límites.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "El amor es poesía; la religión es amor. \"Dos cosas semejantes a una tercera, son iguales entre sí\".", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "El amor es un misterio. Todo en él son fenómenos a cual más inexplicable; todo en él es ilógico, todo en él es vaguedad y absurdo.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Todo el mundo siente. Sólo a algunos seres les es dado el guardar, como un tesoro, la memoria viva de lo que han sentido. Yo creo que éstos son los poetas. Es más, creo que únicamente por esto lo son.", Author = "Gustavo Adolfo Bécquer" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Gustavo_Adolfo_Bécquer", Text = "Dios, aunque invisible, tiene siempre una mano tendida para levantar por un extremo la carga que abruma al pobre.", Author = "Gustavo Adolfo Bécquer" },
